function everestWaypoint(point) {
  if(!point||typeof point.east!=='number'||typeof point.north!=='number'||!isFinite(point.east)||!isFinite(point.north))return null;
  return {east:Math.round(clamp(point.east,-8750,8750)),north:Math.round(clamp(point.north,-8750,8750))};
}
function everestWaypointInfo(data,pose,point) {
