  var view=everestFlightPose(pose),east=target.east-view.east,north=target.north-view.north,range=Math.hypot(east,north),
    altitude=everestHeight(data,target.east/8849,-target.north/8849)*8849,visible=true,steps=clamp(Math.ceil(range/75),2,256);
  // Test the sampled surface along the line of sight. This marker is a
  // navigation overlay; its 40 m offset does not alter the measured terrain.
  for(var i=1;i<steps;i++){
    var t=i/steps,ground=everestHeight(data,(view.east+east*t)/8849,-(view.north+north*t)/8849)*8849;
    if(ground+8>view.altitude+(altitude+40-view.altitude)*t){visible=false;break;}
  }
  return {point:target,range:range,bearing:range<.5?null:((Math.atan2(east,north)*180/Math.PI)+360)%360,altitude:altitude,visible:visible};
}
