function everestSurfaceMaterial(){
  var mat=material('#ffffff',{vertexColors:true,roughness:.94,bumpMap:grainTexture,bumpScale:.00006});
  mat.name='everestRockAndSnow';
  mat.onBeforeCompile=function(shader){
    shader.vertexShader='varying vec3 vAlpineMeters;varying vec3 vAlpineNormal;\n'+shader.vertexShader;
    shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvAlpineMeters=position*8849.;vAlpineNormal=normal;');
    // The texture repeats every 64 m instead of stretching across 18 km.
    shader.vertexShader=shader.vertexShader.replace('#include <uv_vertex>','#include <uv_vertex>\nvUv=position.xz*8849./64.;');
    shader.fragmentShader=[
      'varying vec3 vAlpineMeters;varying vec3 vAlpineNormal;',
      'float alpineHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}',
      'float alpineNoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(alpineHash(i),alpineHash(i+vec2(1.,0.)),f.x),mix(alpineHash(i+vec2(0.,1.)),alpineHash(i+vec2(1.)),f.x),f.y);}'
    ].join('\n')+'\n'+shader.fragmentShader;
    shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>',[
      '#include <color_fragment>',
      'vec3 alpineP=vAlpineMeters,alpineN=normalize(vAlpineNormal);',
      'float alpineBroken=alpineNoise(alpineP.xz*.013)+alpineNoise(alpineP.xy*.018)*.35;',
      'float alpineCover=smoothstep(5400.,6600.,alpineP.y+(alpineBroken-.65)*300.)*smoothstep(.58,.86,alpineN.y+(alpineBroken-.65)*.12);',
      'float alpineLayers=.5+.5*sin(alpineP.y*.085+alpineP.x*.011+alpineNoise(alpineP.xz*.004)*5.);',
      'float alpineFootprint=max(length(dFdx(alpineP)),length(dFdy(alpineP)));',
      'float alpineFine=(alpineNoise(alpineP.xz*.4)-.5)*(1.-smoothstep(2.,18.,alpineFootprint));',
      'vec3 alpineRock=mix(vec3(.052,.057,.059),vec3(.16,.145,.122),alpineBroken*.5+alpineLayers*.22)*(1.+alpineFine*.22);',
      'float alpineDrift=.5+.5*sin(alpineP.x*.09+alpineP.z*.043+alpineBroken*3.);',
      'vec3 alpineSnow=mix(vec3(.49,.61,.69),vec3(.72,.78,.81),.68+alpineDrift*.22)*(1.+alpineFine*.06);',
      'diffuseColor.rgb=mix(alpineRock,alpineSnow,alpineCover);'
    ].join('\n'));
    shader.fragmentShader=shader.fragmentShader.replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor=mix(.97,.84,alpineCover);');
  };
  mat.customProgramCacheKey=function(){return 'everest-surface-2';};return mat;
}
