  point={east:point.east,north:point.north};
  if(ev.key==='ArrowLeft')point.east-=step;else if(ev.key==='ArrowRight')point.east+=step;
  else if(ev.key==='ArrowUp')point.north+=step;else if(ev.key==='ArrowDown')point.north-=step;
  else if(ev.key==='Home')point=everestPosition();else if(ev.key==='Delete'||ev.key==='Backspace')point=null;else return;
